import{_ as l,a0 as n,w as p,s as r,I as t,x as s,ao as a,a1 as d,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Bash 中的 ＆ 符號和文件描述符 | LCTT x X-CMD","titleTemplate":false,"description":"Bash 中的 ＆ 符號和文件描述符 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Bash 中的 ＆ 符號和文件描述符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Bash 中的 ＆ 符號和文件描述符 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190212 Ampersands and File Descriptors in Bash","title":"Bash 中的 ＆ 符號和文件描述符","tag":"201903","desc":""},"relativePath":"201903/20190212 Ampersands and File Descriptors in Bash.md","filePath":"[post].md"}'),c={name:"201903/20190212 Ampersands and File Descriptors in Bash.md"};function g(h,e,u,k,b,f){const i=n("Link");return p(),r("div",null,[e[31]||(e[31]=t("h1",{id:"bash-中的-符號和文件描述符",tabindex:"-1"},[s("Bash 中的 ＆ 符號和文件描述符 "),t("a",{class:"header-anchor",href:"#bash-中的-符號和文件描述符","aria-label":"Permalink to “Bash 中的 ＆ 符號和文件描述符”"},"​")],-1)),e[32]||(e[32]=t("blockquote",null,[t("p",null,"瞭解如何將 “＆” 與尖括號結合使用，並從命令列中獲得更多信息。")],-1)),e[33]||(e[33]=t("p",null,[t("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/ampersand-coffee.png?itok=yChaT-47",alt:""})],-1)),t("p",null,[e[1]||(e[1]=a("在我們探究大多數鏈式 Bash 命令中出現的所有的雜項符號（<code>&amp;</code>、<code>|</code>、<code>;</code>、<code>&gt;</code>、<code>&lt;</code>、<code>{</code>、<code>[</code>、<code>(</code>、<code>)</code>、<code>]</code>、<code>}</code> 等等）的任務中，",23)),d(i,{href:"https://linux.cn/article-10587-1.html"},{default:o(()=>[...e[0]||(e[0]=[s("我們一直在仔細研究 & 符號",-1)])]),_:1}),e[2]||(e[2]=s("。",-1))]),t("p",null,[d(i,{href:"https://linux.cn/article-10587-1.html"},{default:o(()=>[...e[3]||(e[3]=[s("上次，我們看到了如何使用 & 把可能需要很長時間運行的進程放到後台運行",-1)])]),_:1}),e[4]||(e[4]=s("。但是，",-1)),e[5]||(e[5]=t("code",null,"＆",-1)),e[6]||(e[6]=s(" 與尖括號 ",-1)),e[7]||(e[7]=t("code",null,"<",-1)),e[8]||(e[8]=s(" 結合使用，也可用於將輸出或輸出通過管道導向其他地方。",-1))]),t("p",null,[e[11]||(e[11]=s("在 ",-1)),d(i,{href:"https://linux.cn/article-10502-1.html"},{default:o(()=>[...e[9]||(e[9]=[s("前面的",-1)])]),_:1}),e[12]||(e[12]=s()),d(i,{href:"https://linux.cn/article-10529-1.html"},{default:o(()=>[...e[10]||(e[10]=[s("尖括號教程中",-1)])]),_:1}),e[13]||(e[13]=s("，你看到了如何使用 ",-1)),e[14]||(e[14]=t("code",null,">",-1)),e[15]||(e[15]=s("，如下：",-1))]),e[34]||(e[34]=a('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls &gt; list.txt</span></span></code></pre></div><p>將 <code>ls</code> 輸出傳遞給 <code>list.txt</code> 文件。</p><p>現在我們看到的是簡寫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls 1&gt; list.txt</span></span></code></pre></div><p>在這種情況下，<code>1</code> 是一個文件描述符，指向標準輸出（<code>stdout</code>）。</p><p>以類似的方式，<code>2</code> 指向標準錯誤輸出（<code>stderr</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls 2&gt; error.log</span></span></code></pre></div><p>所有錯誤消息都通過管道傳遞給 <code>error.log</code> 文件。</p><p>回顧一下：<code>1&gt;</code> 是標準輸出（<code>stdout</code>），<code>2&gt;</code> 是標準錯誤輸出（<code>stderr</code>）。</p><p>第三個標準文件描述符，<code>0&lt;</code> 是標準輸入（<code>stdin</code>）。你可以看到它是一個輸入，因為箭頭（<code>&lt;</code>）指向<code>0</code>，而對於 <code>1</code> 和 <code>2</code>，箭頭（<code>&gt;</code>）是指向外部的。</p><h3 id="標準文件描述符有什麼用" tabindex="-1">標準文件描述符有什麼用？ <a class="header-anchor" href="#標準文件描述符有什麼用" aria-label="Permalink to “標準文件描述符有什麼用？”">​</a></h3><p>如果你在閲讀本系列以後，你已經多次使用標準輸出（<code>1&gt;</code>）的簡寫形式：<code>&gt;</code>。</p><p>例如，當（假如）你知道你的命令會拋出一個錯誤時，像 <code>stderr</code>（<code>2</code>）這樣的東西也很方便，但是 Bash 告訴你的東西是沒有用的，你不需要看到它。如果要在 <code>home/</code> 目錄中創建目錄，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir</span></span></code></pre></div><p>如果 <code>newdir/</code> 已經存在，<code>mkdir</code> 將顯示錯誤。但你為什麼要關心這些呢？（好吧，在某些情況下你可能會關心，但並非總是如此。）在一天結束時，<code>newdir</code> 會以某種方式讓你填入一些東西。你可以通過將錯誤消息推入虛空（即 ``/dev/null`）來抑制錯誤消息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir 2&gt; /dev/null</span></span></code></pre></div><p>這不僅僅是 “讓我們不要看到醜陋和無關的錯誤消息，因為它們很煩人”，因為在某些情況下，錯誤消息可能會在其他地方引起一連串錯誤。比如説，你想找到 <code>/etc</code> 下所有的 <code>.service</code> 文件。你可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot;</span></span></code></pre></div><p>但事實證明，在大多數系統中，<code>find</code> 顯示的錯誤會有許多行，因為普通用户對 <code>/etc</code> 下的某些文件夾沒有讀取訪問權限。它使讀取正確的輸出變得很麻煩，如果 <code>find</code> 是更大的腳本的一部分，它可能會導致行中的下一個命令排隊。</p><p>相反，你可以這樣做：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt; /dev/null</span></span></code></pre></div><p>而且你只得到你想要的結果。</p><h3 id="文件描述符入門" tabindex="-1">文件描述符入門 <a class="header-anchor" href="#文件描述符入門" aria-label="Permalink to “文件描述符入門”">​</a></h3><p>單獨的文件描述符 <code>stdout</code> 和 <code>stderr</code> 還有一些注意事項。如果要將輸出存儲在文件中，請執行以下操作：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt; services.txt</span></span></code></pre></div><p>工作正常，因為 <code>1&gt;</code> 意味着 “發送標準輸出且自身標準輸出（非標準錯誤）到某個地方”。</p><p>但這裏存在一個問題：如果你想把命令拋出的錯誤信息記錄到文件，而結果中沒有錯誤信息你該怎麼<strong>做</strong>？上面的命令並不會這樣做，因為它只寫入 <code>find</code> 正確的結果，而：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt; services.txt</span></span></code></pre></div><p>只會寫入命令拋出的錯誤信息。</p><p>我們如何得到兩者？請嘗試以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; &amp;&gt; services.txt</span></span></code></pre></div><p>…… 再次和 <code>&amp;</code> 打個招呼！</p><p>我們一直在説 <code>stdin</code>（<code>0</code>）、<code>stdout</code>（<code>1</code>）和 <code>stderr</code>（<code>2</code>）是“文件描述符”。文件描述符是一種特殊構造，是指向文件的通道，用於讀取或寫入，或兩者兼而有之。這來自於將所有內容都視為文件的舊 UNIX 理念。想寫一個設備？將其視為文件。想寫入套接字並通過網絡發送數據？將其視為文件。想要讀取和寫入文件？嗯，顯然，將其視為文件。</p><p>因此，在管理命令的輸出和錯誤的位置時，將目標視為文件。因此，當你打開它們來讀取和寫入它們時，它們都會獲得文件描述符。</p><p>這是一個有趣的效果。例如，你可以將內容從一個文件描述符傳遞到另一個文件描述符：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt; services.txt 2&gt;&amp;1</span></span></code></pre></div><p>這會將 <code>stderr</code> 導向到 <code>stdout</code>，而 <code>stdout</code> 通過管道被導向到一個文件中 <code>services.txt</code> 中。</p><p>它再次出現：<code>&amp;</code> 發信號通知 Bash <code>1</code> 是目標文件描述符。</p><p>標準文件描述符的另一個問題是，當你從一個管道傳輸到另一個時，你執行此操作的順序有點違反直覺。例如，按照上面的命令。它看起來像是錯誤的方式。你應該像這樣閲讀它：“將輸出導向到文件，然後將錯誤導向到標準輸出。” 看起來錯誤輸出會在後面，並且在輸出到標準輸出（<code>1</code>）已經完成時才發送。</p><p>但這不是文件描述符的工作方式。文件描述符不是文件的佔位符，而是文件的輸入和（或）輸出通道。在這種情況下，當你做 <code>1&gt; services.txt</code> 時，你的意思是 “打開一個寫管道到 <code>services.txt</code> 並保持打開狀態”。<code>1</code> 是你要使用的管道的名稱，它將保持打開狀態直到該行的結尾。</p><p>如果你仍然認為這是錯誤的方法，試試這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 2&gt;&amp;1 1&gt;services.txt</span></span></code></pre></div><p>並注意它是如何不工作的；注意錯誤是如何被導向到終端的，而只有非錯誤的輸出（即 <code>stdout</code>）被推送到 <code>services.txt</code>。</p><p>這是因為 Bash 從左到右處理 <code>find</code> 的每個結果。這樣想：當 Bash 到達 <code>2&gt;&amp;1</code> 時，<code>stdout</code> （<code>1</code>）仍然是指向終端的通道。如果 <code>find</code> 給 Bash 的結果包含一個錯誤，它將被彈出到 <code>2</code>，轉移到 <code>1</code>，然後留在終端！</p><p>然後在命令結束時，Bash 看到你要打開 <code>stdout</code>（<code>1</code>） 作為到 <code>services.txt</code> 文件的通道。如果沒有發生錯誤，結果將通過通道 <code>1</code> 進入文件。</p><p>相比之下，在：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>find /etc -iname &quot;*.service&quot; 1&gt;services.txt 2&gt;&amp;1</span></span></code></pre></div><p><code>1</code> 從一開始就指向 <code>services.txt</code>，因此任何彈出到 <code>2</code> 的內容都會導向到 <code>1</code> ，而 <code>1</code> 已經指向最終去的位置 <code>services.txt</code>，這就是它工作的原因。</p><p>在任何情況下，如上所述 <code>&amp;&gt;</code> 都是“標準輸出和標準錯誤”的縮寫，即 <code>2&gt;&amp;1</code>。</p><p>這可能有點多，但不用擔心。重新導向文件描述符在 Bash 命令列和腳本中是司空見慣的事。隨着本系列的深入，你將瞭解更多關於文件描述符的知識。下週見!</p><hr>',51)),t("p",null,[e[17]||(e[17]=s("via: ",-1)),d(i,{href:"https://www.linux.com/blog/learn/2019/2/ampersands-and-file-descriptors-bash"},{default:o(()=>[...e[16]||(e[16]=[s("https://www.linux.com/blog/learn/2019/2/ampersands-and-file-descriptors-bash",-1)])]),_:1})]),t("p",null,[e[22]||(e[22]=s("作者：",-1)),d(i,{href:"https://www.linux.com/users/bro66"},{default:o(()=>[...e[18]||(e[18]=[s("Paul Brown",-1)])]),_:1}),e[23]||(e[23]=s(" 選題：",-1)),d(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...e[19]||(e[19]=[s("lujun9972",-1)])]),_:1}),e[24]||(e[24]=s(" 譯者：",-1)),d(i,{href:"https://github.com/zero-mk"},{default:o(()=>[...e[20]||(e[20]=[s("zero-mk",-1)])]),_:1}),e[25]||(e[25]=s(" 校對：",-1)),d(i,{href:"https://github.com/wxy"},{default:o(()=>[...e[21]||(e[21]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[28]||(e[28]=s("本文由 ",-1)),d(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...e[26]||(e[26]=[s("LCTT",-1)])]),_:1}),e[29]||(e[29]=s(" 原創編譯，",-1)),d(i,{href:"https://linux.cn/"},{default:o(()=>[...e[27]||(e[27]=[s("Linux中國",-1)])]),_:1}),e[30]||(e[30]=s(" 榮譽推出",-1))])])}const C=l(c,[["render",g]]);export{x as __pageData,C as default};
